def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))
    vrails = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) > h // 2]
    hrails = [r for r in range(h) if sum(v == 2 for v in grid[r]) > w // 2]
    for r, c in centers:
        if c in vrails:
            # Vertical source rail: horizontal ray from the ring center.
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for x in vrails:
                if x == c:
                    continue
                for rr in (r - 1, r + 1):
                    for cc in (x - 1, x, x + 1):
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                            out[rr][cc] = 1
        elif r in hrails:
            # Horizontal source rail: vertical ray from the ring center.
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in hrails:
                if y == r:
                    continue
                for cc in (c - 1, c + 1):
                    if 0 <= cc < w and grid[y][cc] == 0:
                        out[y][cc] = 1
                for rr in (y - 1, y + 1):
                    for cc in (c - 1, c, c + 1):
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                            out[rr][cc] = 1
    return out
